cat << 'PYEOF' | /root/miniconda3/bin/python
import json, numpy as np

with open("/root/autodl-tmp/contrastive_trace_safety/artifacts/diagnostics/gru256_per_seed_results.json") as f:
    data = json.load(f)

models = ["GRU-single", "GRU-multi", "LR-single", "LR-multi"]
seeds = [42, 123, 456]

# Compute mean/std
stats = {}
for m in models:
    vals = {k: [] for k in ["acc", "precision", "fpr", "crossing_rate", "lead_mean"]}
    for s in seeds:
        key = f"{m}_seed{s}"
        for k in vals:
            v = data[key][k]
            if v is not None:
                vals[k].append(v)
    stats[m] = {}
    for k in vals:
        if vals[k]:
            stats[m][k] = (np.mean(vals[k]), np.std(vals[k]))
        else:
            stats[m][k] = (None, None)

# Print summary
print("=== Mean ± Std ===")
print(f"{'Model':<12} {'Acc':>12} {'Prec':>12} {'FPR':>12} {'Cross%':>12} {'Lead':>12}")
for m in models:
    s = stats[m]
    print(f"{m:<12} {s['acc'][0]:.4f}±{s['acc'][1]:.4f} {s['precision'][0]:.4f}±{s['precision'][1]:.4f} {s['fpr'][0]:.4f}±{s['fpr'][1]:.4f} {s['crossing_rate'][0]:.4f}±{s['crossing_rate'][1]:.4f} {s['lead_mean'][0]:.2f}±{s['lead_mean'][1]:.2f}")
PYEOF
